    // register-blocked thread outputs (16 accumulators per thread),
    // using a 64x32 A tile and a 32x64 B tile staged through shared
    // memory (K = 32 fully unrolled). Doubling the per-thread register
    // tile (vs. the previous 2x2 version) quarters the CTA/grid count
    // and doubles arithmetic intensity per shared-memory load (16 FMAs
    // per 8 shared loads vs. 4 FMAs per 4 shared loads), improving
    // reuse of the A/B operand tiles already staged in shared memory.
    mov.u32 %r1, %tid.x;      // tx (0..15)
    mov.u32 %r2, %tid.y;      // ty (0..15)
    mov.u32 %r3, %ctaid.x;    // bx
    mov.u32 %r4, %ctaid.y;    // by
