    mad.lo.u32 %r6, %r3, 64, %r1;   // col0 = bx*64 + tx
    mad.lo.u32 %r7, %r4, 64, %r2;   // row0 = by*64 + ty
    add.u32 %r8, %r6, 16;           // col1
    add.u32 %r9, %r6, 32;           // col2
    add.u32 %r10, %r6, 48;          // col3
    add.u32 %r11, %r7, 16;          // row1
